/* Diagnostic report only, emitted before quality publication. */
static bool floor_write_report(const char *prefix,const bounce_floor_work*w,const fox_transport_context*tx,bool enabled,bool zero,unsigned case_index,bool complete){
 char path[4096];snprintf(path,sizeof path,"%s.floor.json",prefix);FILE*f=fopen(path,"w");if(!f)return false;
 fprintf(f,"{\"version\":\"host-floor-direct-v1\",\"complete\":%s,\"enabled\":%s,\"zeroRhoControl\":%s,\"caseIndex\":%u,\"workBytes\":%zu,\"contextBytes\":%zu,\"resultBytes\":%zu,\"groundDescriptorBytes\":%zu,\"separateHostWorkContract\":true,\"old8MCombinedAdmission\":false,\"limitTotal\":%llu,\"usedTotal\":%llu,\"shaderLimit\":%llu,\"floorHitLimit\":%llu,\"shaderCalls\":%llu,\"floorHits\":%llu,\"evaluations\":%llu,\"zeroRhoHits\":%llu,\"tangentHits\":%llu,\"kernelReservations\":%llu,\"floorQueries\":%llu,\"rho\":[%.17g,%.17g,%.17g],\"categories\":{",complete?"true":"false",enabled?"true":"false",zero?"true":"false",case_index,sizeof*w,sizeof*tx,sizeof(bounce_result),sizeof(bounce_ground),(unsigned long long)w->limit_total,(unsigned long long)w->used_total,(unsigned long long)w->shader_limit,(unsigned long long)w->floor_hit_limit,(unsigned long long)w->shader_calls,(unsigned long long)w->floor_hits,(unsigned long long)w->evaluations,(unsigned long long)w->zero_rho_hits,(unsigned long long)w->tangent_hits,(unsigned long long)(w->evaluations*48),(unsigned long long)tx->counters.primary_ground_direct_queries,tx->ground.rho[0],tx->ground.rho[1],tx->ground.rho[2]);
 for(unsigned i=0;i<BOUNCE_FW_COUNT;i++)fprintf(f,"%s\"%s\":{\"limit\":%llu,\"used\":%llu}",i?",":"",bounce_floor_work_category_name(i),(unsigned long long)w->limit[i],(unsigned long long)w->used[i]);
 bool ok=fputs("}}\n",f)!=EOF;return fclose(f)==0&&ok;
}
